import sys


def count_combinations(n, m):
    s = n - 3
    if s < 0:
        return 0

    def f(t):
        if t < 0:
            return 0
        return (t + 2) * (t + 1) // 2

    ans = f(s) - 3 * f(s - m) + 3 * f(s - 2 * m) - f(s - 3 * m)
    return max(0, ans)


